/**
 * Gingey Wastes missions: one fixed layout per expedition location. Pacing
 * loosely follows Vermintide 2 missions; layouts are original.
 *
 * Besides the normal level characters (see `parseLevel`), authored missions use:
 *   H  hold objective zone (section 1)    1  gate opened when the hold ends
 *   K  mini-boss objective zone (section 2) 2  gate opened when the mini-boss dies
 *   B  boss arena, whole room (section 3)   3  exit gate, opened when the boss dies
 *   b  barrel spot (the run seed keeps about two thirds)
 *
 * Missions with a custom `sections` list (Hallowed Rampart) can also use:
 *   C  cannon tile (hold E to fire; its gate is the rubble wall it breaches)
 *   R  bell temple zone   L  bell tile   V  bell wave spawn (both inside R)
 *   4  temple doorway that seals while the bell event runs
 *
 * Weeping Quarry sets `theme: "mine"` so the client paints crumbling rock
 * walls, cart tracks, wall lanterns and debris props on DECOR_MINE floors.
 */
import type { ExpeditionLocationId } from "../data/expedition";
import type { AuthoredMission } from "../procgen/authoredMission";

